INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(26101, 'Acts 9:14', 'Acts', 9, 14, '&nbsp;او هغه د مشرانو اِمامانو نه دې اختيار سره دلته راغلے دے چې هغه ټول خلق ګرفتار کړى څوک چې ستا نوم يادوى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26102, 'Acts 9:15', 'Acts', 9, 15, '&nbsp;خو مالِک هغۀ ته وفرمائيل چې، ”تۀ لاړ شه ځکه چې دا سړے ما غوره کړے دے څوک چې به غېرو يهوديانو او د هغوئ بادشاهانو او بنى اِسرائيلو ته زما نوم بيان کړى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26103, 'Acts 9:16', 'Acts', 9, 16, '&nbsp;او زۀ به په خپله هغۀ ته وښايم چې هغه به زما د نوم د خاطره څومره تکليف وزغمى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26104, 'Acts 9:17', 'Acts', 9, 17, '&nbsp;نو بيا حنانياس روان شو او هغه کور ته ورننوتو او د ساؤل په سر يې خپل لاس کېښودو او وې وئيل چې، ”زما وروره ساؤله، کله چې تۀ دلته راروان وې کوم مالِک عيسىٰ چې تا ته په لارې خپل ځان څرګند کړو، هغۀ زۀ تا له رالېږلے يم چې ستا نظر دوباره راشى او تۀ د روحُ القُدس نه معمور شې.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26105, 'Acts 9:18', 'Acts', 9, 18, '&nbsp;او سمدستى لکه د پوټکى په شان څيز د ساؤل د سترګو نه لرى شو او هغه واپس بينا شو. بيا هغه پاڅېدو او بپتسمه يې واخسته.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26106, 'Acts 9:19', 'Acts', 9, 19, '&nbsp;او د روټۍ خوړلو نه پس د هغۀ په وجود کښې طاقت راغلو. بيا ساؤل په دمشق کښې يو څو ورځې د عيسىٰ مريدانو سره پاتې شو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26107, 'Acts 9:20', 'Acts', 9, 20, '&nbsp;نو هغۀ سمدستى په عبادتخانو کښې بيان شروع کړو چې عيسىٰ د خُدائ پاک زوئ دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26108, 'Acts 9:21', 'Acts', 9, 21, '&nbsp;هغوئ ټولو چې د هغۀ واورېدل نو حق حېران شول او وې وئيل چې، ”دا هغه سړے نۀ دے چا چې په يروشلم کښې هغه خلق وژل چې د عيسىٰ نوم به يې اخستلو؟ او ولې دے دلته د دې دپاره نۀ دے راغلے چې دغه خلق ګرفتار کړى او مشر اِمام ته يې لاس تړلى بوځى؟“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26109, 'Acts 9:22', 'Acts', 9, 22, '&nbsp;خو ساؤل په خبرو نور هم تکړه کېدو او د دمشق يهوديان يې په خپلو مضبوطو دلائيلو خاموشه کول چې عيسىٰ هم مسيح دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26110, 'Acts 9:23', 'Acts', 9, 23, '&nbsp;د ډېرو ورځو تېرېدو نه وروستو يهوديان راغونډ شول او د ساؤل د مرګ سازش يې وکړو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26111, 'Acts 9:24', 'Acts', 9, 24, '&nbsp;هغوئ شپه او ورځ د ښار د دروازو څوکۍ کوله، د دې دپاره چې هغه قتل کړى. خو ساؤل د هغوئ په سازش پوهه شو', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26112, 'Acts 9:25', 'Acts', 9, 25, '&nbsp;او د هغۀ مريدانو هغه شپه په شپه د ښار په دېوال په يوه بانګۍ کښې لاندې کوز کړو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26113, 'Acts 9:26', 'Acts', 9, 26, '&nbsp;کله چې ساؤل يروشلم ته راورسېدو نو هغۀ کوشش وکړو چې مريدانو سره يو ځائ شى خو هغوئ ټول د هغۀ نه يرېدل ځکه چې د هغوئ په دې يقين نۀ راتلو چې هغۀ ايمان راوړے دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26114, 'Acts 9:27', 'Acts', 9, 27, '&nbsp;خو برنباس هغه بوتلو او رسولانو له يې راوستو. هغۀ هغوئ ته ووئيل چې، ساؤل په سفر کښې مالِک څنګه وليدو او مالِک هغۀ سره خبرې څنګه وکړې، او هغۀ په دمشق کښې په زړۀ ورتيا سره د عيسىٰ په نوم بيان څنګه وکړو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26115, 'Acts 9:28', 'Acts', 9, 28, '&nbsp;بيا ساؤل د هغوئ سره پاتې شو او په يروشلم کښې د هغوئ سره آزاد ګرځېدو، او هغۀ ښۀ په زړۀ ورتيا د مالِک په نوم بيان کولو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26116, 'Acts 9:29', 'Acts', 9, 29, '&nbsp;هغۀ د يونانى يهوديانو سره بحث مباحثه کوله، خو هغوئ د هغۀ د وژلو کوشش وکړو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26117, 'Acts 9:30', 'Acts', 9, 30, '&nbsp;کله چې ايمانداران د دې نه خبر شول نو هغوئ هغه تر قيصريه پورې بوتلو او ترسس ته يې ولېږلو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26118, 'Acts 9:31', 'Acts', 9, 31, '&nbsp;په دې دوران کښې په ټوله يهوديه، ګليل او سامريه کښې جماعتونه په امن وُو او دا نور هم مضبوطېدل او د مالِک په يره کښې يې د روحُ القُدس په مدد سره ترقى موندله او د هغوئ شمېر زياتېدو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26119, 'Acts 9:32', 'Acts', 9, 32, '&nbsp;پطروس په ټول مُلک کښې ځائ په ځائ ګرځېدو او هغه د مقدسينو د ليدو دپاره د لدې کلى ته هم لاړو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26120, 'Acts 9:33', 'Acts', 9, 33, '&nbsp;هلته هغۀ اينياس نومې سړے وليدلو چې د اتو کالو راسې په کټ کښې شل پروت وو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26121, 'Acts 9:34', 'Acts', 9, 34, '&nbsp;پطروس هغۀ ته ووئيل چې، ”اينياسه، عيسىٰ مسيح تا له شفا درکوى. پاڅه او بستره دې ونغاړه.“ او اينياس سمدستى پاڅېدلو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26122, 'Acts 9:35', 'Acts', 9, 35, '&nbsp;هغه خلق چې په لده او شارون کښې اوسېدل هغوئ هغه وليدو او په مالِک يې ايمان راوړو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26123, 'Acts 9:36', 'Acts', 9, 36, '&nbsp;په يافا کښې تبيتا نومې يوه مريده وه چې په يونانۍ کښې ورته ډورکاس يعنې هوسۍ وائى، هغې همېشه نېک کارونه کول او د غريبانانو مدد به يې کولو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26124, 'Acts 9:37', 'Acts', 9, 37, '&nbsp;په دغه وخت کښې هغه ناجوړه شوه او مړه شوه او د هغې مړى له غسل ورکړے شو او د هغې لاش يې پاس په بالاخانه کښې کېښودو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26125, 'Acts 9:38', 'Acts', 9, 38, '&nbsp;د لدې کلے د يافا سره نزدې وو نو کله چې مريدانو واورېدل چې پطروس په لده کښې دے، هغوئ ورپسې دوه سړى ورولېږل او خواست يې ورته وکړو چې، ”مهربانى وکړه زر تر زره مونږ ته ځان راورسوه.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26126, 'Acts 9:39', 'Acts', 9, 39, '&nbsp;نو بيا پطروس هغوئ سره روان شو او کله چې هغه هلته ورسېدو نو پاس بالاخانې ته يې بوتلو. نو ټولې کونډې ښځې پاس بالاخانې ته راټولې شوې وې او په ژړا يې ورته هغه قميصونه او جامې وښودې کومې چې ډورکاس لا ژوندۍ وه نو دوئ له يې جوړې کړې وې.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26127, 'Acts 9:40', 'Acts', 9, 40, '&nbsp;خو پطروس هغوئ ټولې کمرې نه بهر کړې او هغه په سجده شو او دُعا يې وغوښته، بيا هغۀ مړې ښځې ته مخ راواړولو او وې وئيل چې، ”تبيتا، پاڅه.“ هغې خپلې سترګې وغړولې او چې پطروس يې وليدلو نو نېغه کښېناسته.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26128, 'Acts 9:41', 'Acts', 9, 41, '&nbsp;پطروس هغې له لاس ورکړو او هغه يې په پښو ودروله، بيا هغۀ مقدسين او کونډې ښځې راوغوښتې او هغوئ ته يې وښودله چې ژوندۍ ده.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26129, 'Acts 9:42', 'Acts', 9, 42, '&nbsp;دا خبره په ټوله يافا کښې خوره شوه او ډېرو خلقو په مالِک ايمان راوړو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26130, 'Acts 9:43', 'Acts', 9, 43, '&nbsp;نو پطروس څۀ وخت دپاره په يافا کښې د شمعون نومې موچى سره پاتې شو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26131, 'Acts 10:1', 'Acts', 10, 1, '&nbsp;په قيصريه کښې کورنيليوس نومې يو سړے وو چې د اِټالوى پلټنې صوبه دار وو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26132, 'Acts 10:2', 'Acts', 10, 2, '&nbsp;هغه او د هغۀ ټول خاندان دينداره وو او د خُدائ پاک يره ورسره وه او هغۀ خلقو ته ډېر په آزاد لاس سره خېراتونه ورکول او همېشه به يې د خُدائ پاک عبادت کولو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26133, 'Acts 10:3', 'Acts', 10, 3, '&nbsp;يوه ورځ هغۀ د ماسپښين درې بجې رويا وليده چې په کښې يې د خُدائ پاک فرښته صفا وليدله چې هغۀ ته راغله او ورته يې ووئيل چې، ”اے کورنيليوسه.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26134, 'Acts 10:4', 'Acts', 10, 4, '&nbsp;نو کورنيليوس په يرې سره هغې ته کتل او تپوس يې ترې وکړو چې، ”صاحبه، څۀ چل دے؟“ فرښتې جواب ورکړو چې، ”ستا دُعاګانې او غريبانانو ته خېراتونه خُدائ پاک قبول کړى دى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26135, 'Acts 10:5', 'Acts', 10, 5, '&nbsp;اوس يافا ته کسان ولېږه په شمعون پسې چې پطروس ورته وائى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26136, 'Acts 10:6', 'Acts', 10, 6, '&nbsp;هغه د شمعون چميار کره دے چې کور يې د سمندر په غاړه دے.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26137, 'Acts 10:7', 'Acts', 10, 7, '&nbsp;کله چې هغه فرښته چې دۀ سره يې خبرې وکړې رُخصت شوه، نو کورنيليوس خپل دوه نوکران او يو سپاهى چې دينداره سړے وو راوبلل کوم چې د هغۀ ذاتى خِدمتګار وو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26138, 'Acts 10:8', 'Acts', 10, 8, '&nbsp;څۀ چې شوى وُو هغوئ ته يې بيان کړل او يافا ته يې ولېږل.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26139, 'Acts 10:9', 'Acts', 10, 9, '&nbsp;بله ورځ چې هغوئ لا په لاره وُو او ښار ته ورنزدې وُو نو د غرمې په وخت کښې پطروس د دُعا دپاره بره چت ته وختلو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26140, 'Acts 10:10', 'Acts', 10, 10, '&nbsp;هغه اوږے شو او غوښتل يې چې څۀ وخورى، روټۍ لا په تيارېدو کښې وه چې هغۀ رويا وليدله.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26141, 'Acts 10:11', 'Acts', 10, 11, '&nbsp;نو هغۀ په رويا کښې وليدل چې آسمان کولاو شو او يو لوئ څيز لکه د غټ څادر په شان د څلورو ګوټونو نه راځوړند زمکې ته راښکته کيږى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26142, 'Acts 10:12', 'Acts', 10, 12, '&nbsp;په هغۀ کښې هر قسمه ځناور چينجى او ماران او مارغان وُو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26143, 'Acts 10:13', 'Acts', 10, 13, '&nbsp;بيا يو آواز د هغۀ تر غوږه شو او ورته يې وئيل، ”پاڅه، پطروسه، دا حلال کړه او وې خوره.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26144, 'Acts 10:14', 'Acts', 10, 14, '&nbsp;خو پطروس ووئيل چې، ”نه مالِکه، نه. ما هيڅکله هم حرام او ناپاک څيزونه نۀ دى خوړلى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26145, 'Acts 10:15', 'Acts', 10, 15, '&nbsp;او په دوېم ځل بيا د هغۀ هم دا آواز تر غوږه شو او هغۀ ته يې ووئيل، ”هر څۀ چې خُدائ پاک، پاک کړى دى، تۀ هغې ته ناپاکه مۀ وايه.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26146, 'Acts 10:16', 'Acts', 10, 16, '&nbsp;بيا درې ځله هم داسې وشول نو بيا هغه څادر سمدستى آسمان ته پورته کړے شو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26147, 'Acts 10:17', 'Acts', 10, 17, '&nbsp;پطروس لا د دې رويا په ليدلو غمژن وو چې د دې رويا مطلب څۀ دے، نو په هم دې وخت کښې کوم کسان چې کورنيليوس هغۀ ته ورلېږلى وُو هغوئ د شمعون کور پېدا کړو او بهر په دروازه کښې ولاړ وُو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26148, 'Acts 10:18', 'Acts', 10, 18, '&nbsp;هغوئ آواز ورکړو تپوس يې وکړو چې، ”شمعون چې ورته پطروس هم وائى، دلته مېلمه دے؟“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26149, 'Acts 10:19', 'Acts', 10, 19, '&nbsp;خو پطروس لا د هغه رويا په سوچ کښې وو چې روحُ القُدس هغۀ ته ووئيل چې، ”شمعونه، درې سړى درپسې ګرځى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
